// Sectioned Laundry Controller Config
// Click/deploy this once. Phone/TTS are controlled here.

flow.set("laundry_entities", {
    washerActivity: "binary_sensor.washer_activity_washer_running",
    dryerActivity: "binary_sensor.dryer_activity_dryer_running",
    washerDoor: "binary_sensor.washer_door",
    dryerDoor: "binary_sensor.dryer_door",

    washerState: "input_select.washer_state",
    dryerState: "input_select.dryer_state",
    dryerAlert: "input_boolean.dryer_alert",
    laundryLastDone: "input_datetime.laundry_last_done",
    loadCounter: "counter.laundry_loads",
    laundryStatus: "sensor.laundry_status"
});

flow.set("laundry_phone_config", {
    enabled: true,
    // Service names only, without the notify. prefix.
    notifyServices: [
        "mobile_app_pixel_bell",
        "mobile_app_ashers_phone"
    ],
    tags: {
        state: "laundry_state",
        reminder: "laundry_reminder"
    }
});

flow.set("laundry_tts_config", {
    enabled: true,

    silenceWhenEntityOn: "switch.on_air_sign_2_josh_on_air_led_power_2",

    speakerDevice: "09aa5bd9cb63149e10f689141db50016",

    dryerFinished: {
        messages: [
            "Pardon the interruption. The dryer cycle has completed.",
            "Laundry update. The dryer is finished.",
            "The dryer has completed its cycle. Clothes are ready.",
            "Just a heads up. The dryer is done.",
            "Dryer cycle complete. Laundry is ready for retrieval.",
            "Attention please. The dryer has finished.",
            "Your laundry is dry and ready.",
            "The dryer has stopped. Time to collect the laundry.",
            "Laundry status update. Drying is complete.",
            "The dryer is no longer running. Clothes should be ready."
        ],

        language: "en-GB",
        voice: "RyanNeural",
        volume: 0.7,
        led_color: [0, 80, 255],
        led_brightness: 70,
        max_light_duration: 30
    }
});

flow.set("laundry_reminder_config", {
    enabled: true,
    startHour: 8,
    endHour: 22,
    overdueAfterMinutes: 60
});

node.status({ fill: "green", shape: "dot", text: "config loaded" });
return msg;

function cfg() { return flow.get("laundry_entities") || {}; }
function haStates() { return global.get("homeassistant.homeAssistant.states") || {}; }
function haState(entityId) { return entityId ? haStates()[entityId]?.state : undefined; }
function shadow() { return flow.get("laundry_shadow") || {}; }
function setShadow(entityId, state) {
    if (!entityId) return;
    const s = shadow();
    s[entityId] = { state, updated: new Date().toISOString() };
    flow.set("laundry_shadow", s);
}
function shadowState(entityId) { return shadow()[entityId]?.state; }
function shadowUpdated(entityId) { return shadow()[entityId]?.updated; }
function st(entityId) { return haState(entityId) ?? shadowState(entityId); }
function getEventStates(msg) {
    const event = msg.payload?.event ?? msg.payload ?? {};
    const oldObj = event.old_state ?? msg.payload?.old_state;
    const newObj = event.new_state ?? msg.payload?.new_state ?? msg.payload;
    const oldState = typeof oldObj === "object" ? oldObj?.state : oldObj;
    const newState = typeof newObj === "object" ? newObj?.state : newObj;
    return { oldState, newState, oldObj, newObj, entityId: newObj?.entity_id ?? oldObj?.entity_id };
}
function laundryStatusMessage() {
    const c = cfg();
    const status = st(c.laundryStatus);
    if (!status || status === "unknown" || status === "unavailable") {
        return `Washer: ${st(c.washerState) ?? "Unknown"} | Dryer: ${st(c.dryerState) ?? "Unknown"}`;
    }
    return status;
}
function evt(name, extra = {}) { return { payload: { laundry_event: name, ...extra } }; }
function out(payload = {}) { return { payload }; }

const c = cfg();
const { oldState, newState, entityId } = getEventStates(msg);
const washerState = st(c.washerState);
const dryerState = st(c.dryerState);

node.warn({ node: "Washer State Handler", entityId, oldState, newState, washerState, dryerState, shadow: flow.get("laundry_shadow") || {} });
node.status({ fill: "blue", shape: "dot", text: `washer ${oldState ?? "?"} → ${newState ?? "?"}; state=${washerState ?? "?"}` });

let setWashing = null;
let incrementLoad = null;
let setWashDone = null;
let eventOut = null;

if (newState === "on") {
    if (washerState !== "Washing") {
        setShadow(c.washerState, "Washing");
        setWashing = out();
        incrementLoad = out();
        eventOut = evt("washer_started", { message: "Washer started." });
        node.status({ fill: "green", shape: "dot", text: "washer_started → Washing + load++" });
    } else {
        node.status({ fill: "yellow", shape: "ring", text: "washer on ignored; already Washing" });
    }
    return [setWashing, incrementLoad, null, eventOut];
}

if (newState === "off") {
    const wasRunning = oldState === "on" || washerState === "Washing";
    if (!wasRunning) {
        node.status({ fill: "yellow", shape: "ring", text: `washer off ignored; old=${oldState ?? "?"}, state=${washerState ?? "?"}` });
        return [null, null, null, null];
    }

    setShadow(c.washerState, "Wash Done");
    setWashDone = out();

    const eventName = dryerState === "Drying" ? "washer_finished_while_dryer_running" : "washer_finished";
    eventOut = evt(eventName, {
        message: dryerState === "Drying" ? "Washer finished while dryer is running." : "Washer finished! Move clothes to the dryer."
    });

    node.status({ fill: dryerState === "Drying" ? "blue" : "green", shape: "dot", text: `${eventName} → Wash Done` });
    return [null, null, setWashDone, eventOut];
}

node.status({ fill: "yellow", shape: "ring", text: `washer event ignored: ${newState ?? "unknown"}` });
return [null, null, null, null];

