function out(payload = {}) { return { payload }; }

const c = cfg();
const rcfg = flow.get("laundry_reminder_config") || {};

if (!rcfg.enabled) {
    node.status({ fill: "grey", shape: "ring", text: "reminders disabled" });
    return null;
}

const now = new Date();
const hour = now.getHours();
if (hour < rcfg.startHour || hour >= rcfg.endHour) {
    node.status({ fill: "grey", shape: "ring", text: "outside reminder window" });
    return null;
}

const washer = st(c.washerState);
const dryer = st(c.dryerState);
const washerDone = washer === "Wash Done";
const dryerDone = dryer === "Dry Done";

if (!washerDone && !dryerDone) {
    node.status({ fill: "green", shape: "ring", text: "no laundry waiting" });
    return null;
}

function entityChangedAt(entityId) {
    const e = haStates()[entityId];
    return e?.last_changed || shadowUpdated(entityId);
}

function isOverdue(entityId, doneState) {
    if (st(entityId) !== doneState) return false;
    const ts = entityChangedAt(entityId);
    if (!ts) return false;
    return ((new Date()) - new Date(ts)) / 60000 > rcfg.overdueAfterMinutes;
}

const overdue = isOverdue(c.washerState, "Wash Done") || isOverdue(c.dryerState, "Dry Done");
const eventName = overdue ? "laundry_overdue" : "laundry_reminder";

node.warn({ node: "Reminder Event Builder", washer, dryer, overdue, shadow: flow.get("laundry_shadow") || {} });
node.status({ fill: overdue ? "red" : "blue", shape: "dot", text: overdue ? "overdue reminder event" : "normal reminder event" });

return evt(eventName, { message: laundryStatusMessage() });

function cfg() {
    return flow.get("laundry_phone_config") || {};
}

function notifyMsg(service, data) {
    return {
        payload: {
            service,
            data
        }
    };
}

const pcfg = cfg();
const event = msg.payload?.laundry_event;
const tags = pcfg.tags || { state: "laundry_state", reminder: "laundry_reminder" };
const services = pcfg.notifyServices || [];

if (!pcfg.enabled) {
    node.status({ fill: "grey", shape: "ring", text: "phone notifications disabled" });
    return null;
}

if (!services.length) {
    node.status({ fill: "red", shape: "ring", text: "no phone notify services configured" });
    return null;
}

let data = null;

if (event === "washer_finished") {
    data = {
        title: "Laundry",
        message: msg.payload.message || "Washer finished! Move clothes to the dryer.",
        data: {
            tag: tags.state,
            actions: [
                { action: "LAUNDRY_HANG_DRY", title: "Hang Dry (Done)" }
            ]
        }
    };
}

if (event === "dryer_finished") {
    data = {
        title: "Laundry",
        message: msg.payload.message || "Dryer finished.",
        data: {
            tag: tags.state,
            actions: [
                { action: "LAUNDRY_MARK_DONE", title: "Mark as Done" }
            ]
        }
    };
}

if (event === "laundry_reminder" || event === "laundry_overdue") {
    data = {
        title: event === "laundry_overdue" ? "OVERDUE: Laundry!" : "Laundry Reminder",
        message: msg.payload.message || "Laundry is waiting.",
        data: {
            tag: tags.reminder,
            importance: event === "laundry_overdue" ? "high" : "default",
            actions: [
                { action: "LAUNDRY_MARK_DONE", title: "Mark as Done" }
            ]
        }
    };
}

if (event === "clear_laundry_state") {
    data = {
        message: "clear_notification",
        data: { tag: tags.state }
    };
}

if (event === "laundry_cleared") {
    const out = [];
    for (const service of services) {
        out.push(notifyMsg(service, { message: "clear_notification", data: { tag: tags.state } }));
        out.push(notifyMsg(service, { message: "clear_notification", data: { tag: tags.reminder } }));
    }

    node.warn({ node: "Phone Notifier", event, services, messages: out.map(m => m.payload) });
    node.status({ fill: "green", shape: "dot", text: `clear all → ${services.length} phone(s)` });
    return [out];
}

if (!data) {
    node.status({ fill: "grey", shape: "ring", text: `phone ignored: ${event || "no event"}` });
    return null;
}

const out = services.map(service => notifyMsg(service, data));
node.warn({ node: "Phone Notifier", event, services, data });
node.status({ fill: "green", shape: "dot", text: `${event} → ${services.length} phone(s)` });
return [out];

function cfg() {
    return flow.get("laundry_tts_config") || {};
}

function pickRandom(items, fallback) {
    if (!Array.isArray(items) || items.length === 0) {
        return fallback;
    }

    const index = Math.floor(Math.random() * items.length);
    return items[index];
}

const c = cfg();

const event =
    msg.laundry_event ||
    msg.payload?.laundry_event ||
    msg.payload?.event ||
    msg.event;

if (!c.enabled) {
    node.status({
        fill: "grey",
        shape: "ring",
        text: "TTS disabled"
    });

    return null;
}

if (event !== "dryer_finished") {
    node.status({
        fill: "grey",
        shape: "ring",
        text: `ignored: ${event || "no event"}`
    });

    return null;
}

const dryerCfg = c.dryerFinished || {};

const message = pickRandom(
    dryerCfg.messages,
    dryerCfg.message || "The dryer has finished."
);

msg.payload = {
    speaker_device: c.speakerDevice,
    message,
    language: dryerCfg.language || "en-US",
    voice: dryerCfg.voice || "JennyNeural",
    volume: dryerCfg.volume ?? 0.7,
    led_color: dryerCfg.led_color || [0, 80, 255],
    led_brightness: dryerCfg.led_brightness ?? 70,
    max_light_duration: dryerCfg.max_light_duration ?? 30
};

node.status({
    fill: "green",
    shape: "dot",
    text: `TTS allowed: ${message.slice(0, 36)}${message.length > 36 ? "..." : ""}`
});

node.warn({
    node: "TTS Router",
    event,
    selectedMessage: message,
    payload: msg.payload
});

return msg;
